1	import { types as nodeTypes } from 'node:util';
2	
3	const NODE_TYPES = new Set(['trigger', 'form', 'condition', 'action', 'end']);
4	const FIELD_TYPES = new Set(['string', 'number', 'integer', 'boolean']);
5	const FORBIDDEN_SEGMENTS = new Set(['__proto__', 'prototype', 'constructor']);
6	const STRING_BOUNDS = new Set(['minLength', 'maxLength']);
7	const NUMBER_BOUNDS = new Set(['min', 'max']);
8	
9	function assertPlainObject(value, label) {
10	  if (!value || typeof value !== 'object' || Array.isArray(value)) {
11	    throw new TypeError(`${label} must be an object`);
12	  }
13	}
14	
15	function isUsableObject(value) {
16	  return value !== null && typeof value === 'object' && !Array.isArray(value);
17	}
18	
19	function valueMatchesType(value, type) {
20	  if (type === 'string') return typeof value === 'string';
21	  if (type === 'boolean') return typeof value === 'boolean';
22	  if (typeof value !== 'number') return false;
23	  if (type === 'number') return Number.isFinite(value);
24	  return Number.isInteger(value);
25	}
26	
27	function valueSatisfiesBounds(value, spec) {
28	  if (spec.type === 'string') {
29	    const length = [...value].length;
30	    if (spec.minLength !== undefined && length < spec.minLength) return false;
31	    if (spec.maxLength !== undefined && length > spec.maxLength) return false;
32	  } else if (spec.type === 'number' || spec.type === 'integer') {
33	    if (spec.min !== undefined && value < spec.min) return false;
34	    if (spec.max !== undefined && value > spec.max) return false;
35	  }
36	  return true;
37	}
