32	      {
33	        id: 'gate', type: 'condition', then: 'act', else: 'missed',
34	        condition: { field: 'failure.message.label', operator: 'eq', value: 'web' },
35	      },
36	      actNode,
37	      ...extraNodes,
38	      { id: 'done', type: 'end', result: 'finished' },
39	      { id: 'missed', type: 'end', result: 'condition-did-not-see-label' },
40	    ],
41	  };
42	}
