53	  assert.notEqual(message, null);
54	  assert.equal(message.label, 'web', 'label reads along the same path');
55	  assert.deepEqual(message.meta, { source: 'form' });
56	  assert.deepEqual(message.a, { b: { c: 'deep' } }, 'created parents come whole');
