61	  // prototype) and a cause the copy must keep.
62	  const failure = new Error(undefined, { cause: { code: 'upstream' } });
63	  // A second input field aliases the very same Error.
64	  return { failure, holder: { error: failure }, note: 'kept' };
65	}
